//TRANEXTR JOB 'EXTRACT TRAN TYPE',
// CLASS=A,MSGCLASS=0,NOTIFY=&SYSUID
//******************************************************************
//* Copyright Amazon.com, Inc. or its affiliates.
//* All Rights Reserved.
//*
//* Licensed under the Apache License, Version 2.0 (the "License").
